//! A note made over a Job's page: the annotation layer (`annotate.rs`, `capture.rs`) reaching into the page under the pointer,
//! as Classic's Job browser Capture does (`job-browsers.ts` `freeze`, `hold`, `aim` and `note`).
//!
//! | Piece | Where |
//! |---|---|
//! | What the page answered, bounded and worded | [`read`] |
//! | Classic's capture layer, built to run in a page | `read.js` (generated by `apps/desktop/scripts/job-browser-page.mjs`, never edited here) |
//! | The pages a note may be made over, the part at a point, and the part held | this file |
//!
//! **The page is read in a content world of Bridge's own** ([`WORLD`]), which shares the page's DOM and nothing else, so a page's
//! scripts see none of it and a page cannot answer for itself. Every answer is bounded on this side (`read`). **The page holds still
//! as its picture while the layer is armed** (`WebPage::pin`), which is also what the note's picture of the window shows of it.

pub mod read;

use std::time::Duration;

use gpui::{App, AppContext, AsyncApp, Bounds, Entity, FutureExt, Global, Pixels, Point, SharedString, WeakEntity};
use serde_json::{json, Value};

use crate::web::WebPage;

/// The content world a page is read in: Bridge's own, apart from the finder's and an agent's expressions'.
pub const WORLD: &str = "armada-page-note";

/// Classic's capture layer as built: installed in [`WORLD`] once a page load, since a load clears the world.
const READER: &str = include_str!("read.js");

/// A page that does not answer within this is read as nothing.
const ANSWER: Duration = Duration::from_secs(5);

/// The pages a note may be made over: each Job browser's, with the Job it is.
#[derive(Default)]
struct Offered(Vec<(WeakEntity<WebPage>, SharedString)>);

impl Global for Offered {}

/// A Job browser's page, which a note may be made over, and its Job, which the note goes to.
pub fn offer(page: &Entity<WebPage>, job: SharedString, cx: &mut App) {
    let offered = cx.default_global::<Offered>();
    offered.0.retain(|(one, _)| one.upgrade().is_some());
    offered.0.push((page.downgrade(), job));
}

/// The page under a point of the window, and where its viewport is drawn.
#[derive(Clone)]
pub struct Over {
    pub page: Entity<WebPage>,
    /// Where the page's viewport is in the window: a point of the page is `at - origin`.
    pub origin: Point<Pixels>,
    /// Its size in points, which is its viewport's in CSS pixels.
    pub viewport: (f64, f64),
    /// The Job whose browser it is.
    pub job: SharedString,
}

/// The offered page a pane draws at `at`, if one does.
pub fn page_at(at: Point<Pixels>, cx: &App) -> Option<Over> {
    let offered = cx.try_global::<Offered>()?;
    offered.0.iter().filter_map(|(page, job)| Some((page.upgrade()?, job))).find_map(|(page, job)| {
        let (bounds, visible) = page.read(cx).place()?;
        visible.contains(&at).then(|| Over { origin: bounds.origin, viewport: (f64::from(bounds.size.width), f64::from(bounds.size.height)), page, job: job.clone() })
    })
}

impl Over {
    /// The point `at` of the window, as a point of the page.
    pub fn local(&self, at: Point<Pixels>) -> (f64, f64) {
        (f64::from(at.x - self.origin.x), f64::from(at.y - self.origin.y))
    }

    /// The page's address.
    pub fn address(&self, cx: &App) -> String {
        self.page.read(cx).url().unwrap_or_default()
    }
}

/// Holds every offered page still while a layer is armed, and lets them go when it is put away.
#[derive(Default)]
pub struct Freeze(Vec<WeakEntity<WebPage>>);

impl Freeze {
    pub fn new(cx: &mut App) -> Self {
        let pages: Vec<WeakEntity<WebPage>> = cx.try_global::<Offered>().map(|offered| offered.0.iter().map(|(page, _)| page.clone()).collect()).unwrap_or_default();
        let mut held = Vec::new();
        for page in pages {
            if let Some(page) = page.upgrade() {
                page.update(cx, |page, cx| page.pin(cx));
                held.push(page.downgrade());
            }
        }
        Freeze(held)
    }

    pub fn thaw(&mut self, cx: &mut App) {
        for page in std::mem::take(&mut self.0) {
            let _ = page.update(cx, |page, cx| page.unpin(cx));
        }
    }
}

/// The script that asks the installed reader for the part at a point of the page's viewport. It answers `missing` where a page load
/// has cleared the reader, which is then installed, and otherwise the answer's JSON.
fn ask_body(x: f64, y: f64, take: bool) -> String {
    let whole = |value: f64| if value.is_finite() { value.round() as i64 } else { 0 };
    format!("if (typeof ArmadaReader === \"undefined\") return \"missing\";\nreturn JSON.stringify(ArmadaReader.reader.ask({}, {}, {take}));", whole(x), whole(y))
}

/// Reads the part of `over`'s page at `at`, a point of the window: its aim, or its whole take. None: nothing is there, the page did
/// not answer, or what it answered was too long to be the layer's.
pub async fn read_at(over: &Over, at: Point<Pixels>, take: bool, cx: &AsyncApp) -> Option<Value> {
    let (x, y) = over.local(at);
    for _ in 0..2 {
        let rx = over.page.read_with(cx, |page, _| page.call_async(WORLD, &ask_body(x, y, take)));
        let said = match rx.recv().with_timeout(ANSWER, cx.background_executor()).await {
            Ok(Ok(Ok(Some(said)))) => said,
            _ => return None,
        };
        if said == "missing" {
            let rx = over.page.read_with(cx, |page, _| page.evaluate_in(WORLD, READER));
            rx.recv().with_timeout(ANSWER, cx.background_executor()).await.ok()?.ok()?;
            continue;
        }
        if said.len() > read::MOST_ANSWER {
            return None;
        }
        return ipc::decode::<Value>("page note", said.as_bytes()).ok().filter(|answer| !answer.is_null());
    }
    None
}

/// What the pointer is over in a page: its ring in the window, and its words.
#[derive(Clone, Debug)]
pub struct Aim {
    pub bounds: Bounds<Pixels>,
    pub said: SharedString,
}

/// A part of a page held for a note. Its box is in the window, where the ring and the card go.
#[derive(Clone, Debug)]
pub struct PageHeld {
    pub bounds: Bounds<Pixels>,
    pub said: SharedString,
    /// The page's url as loaded.
    pub address: String,
    /// The Job whose browser the page is.
    pub job: SharedString,
    pub read: read::Read,
}

fn bounds_of(rect: read::Rect, origin: Point<Pixels>) -> Bounds<Pixels> {
    Bounds {
        origin: Point { x: origin.x + gpui::px(rect.x as f32), y: origin.y + gpui::px(rect.y as f32) },
        size: gpui::size(gpui::px(rect.width as f32), gpui::px(rect.height as f32)),
    }
}

impl Over {
    /// What an aim answered, as a ring and words in the window.
    pub fn aim(&self, answer: &Value, address: &str) -> Option<Aim> {
        let aimed = read::aimed(answer, self.viewport)?;
        let said = read::said(read::host_of(address).as_deref(), &aimed.words, "");
        Some(Aim { bounds: bounds_of(aimed.rect, self.origin), said: said.into() })
    }

    /// What a take answered, held.
    pub fn held(&self, answer: &Value, address: String) -> Option<PageHeld> {
        let read = read::held(answer, self.viewport)?;
        let said = read::said(read::host_of(&address).as_deref(), &read.words, &read.text);
        Some(PageHeld { bounds: bounds_of(read.rect, self.origin), said: said.into(), address, job: self.job.clone(), read })
    }
}

impl PageHeld {
    /// The element's own tag, which the note records it by.
    pub fn tag(&self) -> &str {
        &self.read.words.tag
    }

    /// What the note's file says of the page and the part held, over what the layer wrote of its own screen: Classic's
    /// `sessionNoteBody` place and state, and the page's address.
    pub fn write_into(&self, raw: &mut Value) {
        let read = &self.read;
        raw["address"] = json!(self.address);
        raw["job"] = json!(self.job);
        raw["selector"] = json!(read.selector);
        raw["element"] = json!({ "tag": read.words.tag, "text": read.text, "label": read.label });
        raw["component"] = json!(read.component);
        raw["owners"] = json!(read.owners);
        raw["screen"] = json!(read.screen);
        raw["layer"] = json!(read.layer);
        raw["location"] = json!(read.location);
        raw["nearby"] = json!(read.nearby);
        raw["stamp"] = json!(read.stamp);
        raw["selected"] = json!(read.selected);
        raw["scenario"] = json!(read::scenario_of(&read.location));
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use gpui::{point, px, size};

    fn held_part() -> PageHeld {
        let read = read::Read {
            rect: read::Rect { x: 1., y: 2., width: 3., height: 4. },
            words: read::Words { role: "button".into(), name: "Google Search".into(), tag: "input".into() },
            text: String::new(),
            label: Some("Search".into()),
            selector: "form > input".into(),
            component: None,
            owners: Vec::new(),
            screen: None,
            layer: None,
            location: "/search?scenario=wide".into(),
            nearby: vec!["Main".into()],
            stamp: Some("src/a.tsx:3".into()),
            selected: Vec::new(),
        };
        PageHeld { bounds: bounds_of(read.rect, point(px(0.), px(0.))), said: "fast.com › button · Google Search".into(), address: "https://fast.com/search?scenario=wide".into(), job: "job-1".into(), read }
    }

    #[gpui::test]
    fn armed_layers_hold_the_job_pages_still_and_the_last_to_go_lets_them_live_again(cx: &mut gpui::TestAppContext) {
        let page = cx.new(|cx| WebPage::for_job_browser(cx));
        cx.update(|cx| offer(&page, "job-1".into(), cx));
        let held = |cx: &mut gpui::TestAppContext| page.read_with(cx, |page, _| page.pinned());
        assert!(!held(cx));
        let mut first = cx.update(Freeze::new);
        assert!(held(cx), "armed: the page holds still");
        // A layer made anew (after a note) before the old one is let go keeps it still.
        let mut second = cx.update(Freeze::new);
        cx.update(|cx| first.thaw(cx));
        assert!(held(cx), "the new layer still holds it");
        cx.update(|cx| second.thaw(cx));
        assert!(!held(cx), "put away: the page goes live again");
        cx.update(|cx| second.thaw(cx));
        assert!(!held(cx), "a layer let go twice lets go once");
        assert!(cx.update(|cx| page_at(point(px(5.), px(5.)), cx)).is_none(), "a page no pane draws is under no point");
    }

    #[test]
    fn a_box_of_the_page_is_a_box_of_the_window() {
        let rect = read::Rect { x: 10., y: 20., width: 150., height: 30. };
        let bounds = bounds_of(rect, point(px(300.), px(80.)));
        assert_eq!((bounds.origin.x, bounds.origin.y), (px(310.), px(100.)));
        assert_eq!(bounds.size, size(px(150.), px(30.)));
    }

    #[test]
    fn the_ask_carries_whole_numbers_and_says_when_the_reader_is_missing() {
        let body = ask_body(10.4, f64::NAN, true);
        assert!(body.contains("ArmadaReader.reader.ask(10, 0, true)"), "{body}");
        assert!(body.starts_with("if (typeof ArmadaReader === \"undefined\") return \"missing\";"));
        assert!(READER.contains("var ArmadaReader="), "Classic's layer, as built");
    }

    #[test]
    fn what_is_held_is_written_into_the_notes_file_with_the_pages_address() {
        let held = held_part();
        let mut raw = json!({ "screen": "Job", "location": "/" });
        held.write_into(&mut raw);
        assert_eq!(raw["address"], "https://fast.com/search?scenario=wide");
        assert_eq!(raw["job"], "job-1");
        assert_eq!(raw["selector"], "form > input");
        assert_eq!(raw["element"]["tag"], "input");
        assert_eq!(raw["element"]["label"], "Search");
        assert_eq!(raw["location"], "/search?scenario=wide");
        assert_eq!(raw["screen"], Value::Null, "Bridge's own screen is not the page's");
        assert_eq!(raw["scenario"], "wide");
        assert_eq!(raw["nearby"][0], "Main");
        assert_eq!(raw["stamp"], "src/a.tsx:3");
        assert_eq!(held.tag(), "input");
    }
}
